from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; q.append((x,y))
                i0=min(a for a,b in cells); i1=max(a for a,b in cells)+1
                j0=min(b for a,b in cells); j1=max(b for a,b in cells)+1
                out.append((c,i0,i1,j0,j1,cells))
    return out
